  for(Track track:tracks){
   LinearLayout entry=row();entry.setPadding(0,dp(SPACE_8),0,dp(SPACE_8));ImageView cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setImageResource(R.drawable.ic_music);cover.setBackground(GlassTheme.coverFrame(this));cover.setClipToOutline(true);cover.setContentDescription(track.title+" artwork");entry.addView(cover,new LinearLayout.LayoutParams(dp(SIZE_COVER),dp(SIZE_COVER)));loadArtwork(track.id,cover);
   LinearLayout words=column();words.setPadding(dp(SPACE_12),0,dp(SPACE_4),0);TextView title=text(track.title,TYPE_BODY);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setTypeface(null,android.graphics.Typeface.BOLD);words.addView(title);words.addView(caption(MusicRepository.local(this,track.id)==null?"YouTube preview":"Downloaded · preview available"));words.setMinimumHeight(dp(SIZE_TOUCH));words.setContentDescription("Preview "+track.title);words.setOnClickListener(v->startPreview(track));entry.addView(words,weight());Button download=ghostButton("↓",()->chooseDownload(track));download.setTextSize(TYPE_SECTION);download.setContentDescription("Download "+track.title);entry.addView(download,new LinearLayout.LayoutParams(dp(SIZE_TOUCH),dp(SIZE_TOUCH)));entry.setOnClickListener(v->startPreview(track));entry.setBackground(GlassTheme.row(this));results.addView(entry);
   File local=MusicRepository.local(this,track.id);if(local!=null){Button play=ghostButton("Play downloaded",()->playLocal(local));play.setContentDescription("Play downloaded "+track.title);results.addView(play);}
  }
