 private void updateDownloads(){
  if(downloadRows==null)return;List<DownloadQueue.Job> jobs=DownloadService.jobs(this);
  if(jobs.isEmpty()&&downloadRows.getChildCount()==0)downloadRows.addView(caption("Your download queue is empty. Add tracks from Search."));
  for(DownloadQueue.Job job:jobs){DownloadItem item=downloadViews.get(job.key);if(item==null){if(downloadViews.isEmpty())downloadRows.removeAllViews();item=new DownloadItem(job);downloadViews.put(job.key,item);downloadRows.addView(item);}item.update();}
 }
 private final class DownloadItem extends LinearLayout {
  final DownloadQueue.Job job;final TextView state;final ProgressBar bar;final Button cancel,retry;final LinearLayout actions;
  DownloadItem(DownloadQueue.Job job){super(MainActivity.this);this.job=job;setOrientation(VERTICAL);setPadding(0,dp(SPACE_12),0,dp(SPACE_12));TextView name=text(job.title,TYPE_BODY);name.setMaxLines(2);addView(name);state=caption("");state.setPadding(0,dp(SPACE_4),0,dp(SPACE_8));addView(state);bar=new ProgressBar(MainActivity.this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setContentDescription("Download progress for "+job.title);addView(bar,new LinearLayout.LayoutParams(-1,dp(SPACE_8)));actions=row();cancel=ghostButton("Cancel",()->downloadAction("cancelJob",job.key));retry=ghostButton("Retry",()->downloadAction("retry",job.key));actions.addView(cancel,weight());actions.addView(retry,weight());addView(actions);state.setOnClickListener(v->{if(!job.error.isEmpty())new AlertDialog.Builder(MainActivity.this).setTitle("Download details").setMessage(job.error).setPositiveButton("Close",null).show();});}
  void update(){state.setText(job.format.toUpperCase(Locale.ROOT)+" · "+job.message);bar.setVisibility(job.pending()?View.VISIBLE:View.GONE);bar.setIndeterminate(job.progress<0);if(job.progress>=0)bar.setProgress(job.progress);cancel.setVisibility(job.pending()?View.VISIBLE:View.GONE);boolean failed="failed".equals(job.state)||"saveFailed".equals(job.state)||"interrupted".equals(job.state)||"cancelled".equals(job.state);retry.setVisibility(failed?View.VISIBLE:View.GONE);retry.setText("saveFailed".equals(job.state)?"Retry saving":"Retry");actions.setVisibility(job.pending()||failed?View.VISIBLE:View.GONE);}
 }
 private void downloadAction(String action,String key){startForegroundService(new Intent(this,DownloadService.class).setAction(action).putExtra("job",key));handler.postDelayed(this::updateDownloads,200);}
 private void showSleepTimer(){long remaining=SleepTimer.remaining(this);String heading=remaining>0?"Sleep timer · "+((remaining+59999)/60000)+" min left":"Sleep timer";String[] labels={"15 minutes","30 minutes","45 minutes","60 minutes","90 minutes","Turn off"};int[] minutes={15,30,45,60,90,0};new AlertDialog.Builder(this).setTitle(heading).setItems(labels,(d,which)->{SleepTimer.set(this,minutes[which]*60000L);message(minutes[which]==0?"Sleep timer off":"Playback will pause in "+minutes[which]+" minutes.");}).setNegativeButton("Close",null).show();}
