  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Download format").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Download",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{if(!consent.isChecked()){consent.setError("Confirm permission first");return;}String format=formats.getSelectedItemPosition()==0?"mp3":"mp4";dialog.dismiss();beginDownload(t,format);}));dialog.show();
